// Фиктивный провайдер Chat Completions: на запрос с инструментами без результата инструмента
// отдаёт заданный вызов (call.json), иначе — текст "done". Каждый запрос пишет в журнал.
import http from 'node:http';
import fs from 'node:fs';
const [port, callFile, journal] = process.argv.slice(2);
const call = JSON.parse(fs.readFileSync(callFile, 'utf8'));
const chunk = (res, delta, finish) =>
  res.write(`data: ${JSON.stringify({ id: 'c1', object: 'chat.completion.chunk', created: 1, model: 'mock', choices: [{ index: 0, delta, finish_reason: finish ?? null }] })}\n\n`);
http.createServer((req, res) => {
  let body = '';
  req.on('data', (d) => (body += d));
  req.on('end', () => {
    fs.appendFileSync(journal, JSON.stringify({ method: req.method, url: req.url, body: body.slice(0, 200000) }) + '\n');
    if (req.method === 'GET') { res.writeHead(200, { 'content-type': 'application/json' }); return res.end('{"object":"list","data":[{"id":"mock","object":"model"}]}'); }
    let j = {}; try { j = JSON.parse(body); } catch {}
    const msgs = j.messages ?? [];
    const answered = msgs.some((m) => m.role === 'tool');
    const wantsTool = Array.isArray(j.tools) && j.tools.length > 0 && !answered;
    res.writeHead(200, { 'content-type': 'text/event-stream' });
    if (wantsTool) {
      chunk(res, { role: 'assistant', tool_calls: [{ index: 0, id: 'call_stand_1', type: 'function', function: { name: call.name, arguments: JSON.stringify(call.arguments) } }] });
      chunk(res, {}, 'tool_calls');
    } else {
      chunk(res, { role: 'assistant', content: 'done' });
      chunk(res, {}, 'stop');
    }
    res.write(`data: ${JSON.stringify({ id: 'c1', object: 'chat.completion.chunk', created: 1, model: 'mock', choices: [], usage: { prompt_tokens: 1, completion_tokens: 1, total_tokens: 2 } })}\n\n`);
    res.end('data: [DONE]\n\n');
  });
}).listen(Number(port), '127.0.0.1', () => fs.appendFileSync(journal, '{"ready":true}\n'));

