const s = (p) => p.replaceAll(/[^a-zA-Z0-9_-]/g, '_').replaceAll(/_+/g, '_');
const h = (input) => { let x = 2166136261; for (let i = 0; i < input.length; i++) { x ^= input.codePointAt(i); x = Math.trunc(Math.imul(x, 16777619)); } return x.toString(16).padStart(8, '0'); };
const q = (a, b) => { const f = `mcp__${s(a)}__${s(b)}`; if (f.length <= 64) return f; const k = h(f); return `${f.slice(0, 64 - k.length - 1)}_${k}`; };
console.log(q(process.argv[2], process.argv[3]));

sessionHomeKit.session.mts:
// Внутри стенда: окружение и mcp.json дома сессии — сборщиком канона (adapters/kimi-home.ts),
// затем команда с этим окружением. Режим: built — как у раннера; trusted — контроль, доверие
// переменной ПОСЛЕ сборщика; update-on — контроль, автообновление включено после сборщика.
import { spawnSync } from 'node:child_process';
import { readdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
const [canon, mode, ...cmd] = process.argv.slice(2);
const kh = await import(join(canon, 'adapters', 'kimi-home.ts'));
const home = process.env.KIMI_CODE_HOME as string;
// Окружение раннера с каналами, которые сборщик обязан снять.
const runner = { ...process.env, KIMI_CODE_TRUST_WORKSPACE: '1', KIMI_CODE_NO_AUTO_UPDATE: '0' };
const env = kh.kimiSessionEnv(runner, { home, maxTurns: 5 });
writeFileSync(join(home, 'mcp.json'), kh.KIMI_SESSION_MCP);
if (mode === 'trusted') env.KIMI_CODE_TRUST_WORKSPACE = '1';
if (mode === 'update-on') delete env.KIMI_CODE_NO_AUTO_UPDATE;
const problems = kh.kimiIsolationProblems({
    env,
    home,
    humanHome: null,
    listDirFn: (p: string) => readdirSync(p),
});
console.error(`isolation(${mode}): ${JSON.stringify(problems)}`);
const r = spawnSync(cmd[0], cmd.slice(1), { env, stdio: 'inherit' });
process.exit(r.status ?? 1);
